const BANK_TERM_COUNT=17408
const HASH=(v)=>{let h=2166136261>>>0;for(const ch of String(v)){h^=ch.codePointAt(0);h=Math.imul(h,16777619)>>>0}return h.toString(16).padStart(8,'0')}

const ZERO=/[\u200B-\u200F\u2060\uFEFF]/gu
const CJK=/[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}\p{Script=Arabic}\p{Script=Hebrew}]/u
const SAFE_MUTATION_COLLISIONS=new Set(['post','sit','moon','morn','cap','slope'])
function fold(v=''){return String(v||'').normalize('NFKC').replace(ZERO,'').toLocaleLowerCase().replace(/[’]/gu,"'").replace(/\s+/gu,' ').trim()}
function compact(v=''){return fold(v).replace(/[^\p{L}\p{N}]+/gu,'')}
const COMPILED=new Map()
function compiled(locale,category){const key=locale+':'+category;if(COMPILED.has(key))return COMPILED.get(key);const data=(ROWS[locale]?.[category]||[]).map(term=>{const folded=fold(term);return{term,folded,compact:compact(term),bounded:!CJK.test(folded)}}).filter(r=>r.compact&&!SAFE_MUTATION_COLLISIONS.has(r.folded));COMPILED.set(key,data);return data}
const WORD_CHAR=/[\p{L}\p{N}]/u
function hasBoundedTerm(source,term){let at=-1;while((at=source.indexOf(term,at+1))>=0){const before=at>0?source[at-1]:'',after=source[at+term.length]||'';if(!WORD_CHAR.test(before)&&!WORD_CHAR.test(after))return true}return false}
function matches(sourceFolded,row,sourceCompact){return row.bounded?hasBoundedTerm(sourceFolded,row.folded):sourceCompact.includes(row.compact)}
function scanCategory(text,category,ordered,maxHits=12){const sourceFolded=fold(text),sourceCompact=compact(text),hits=[];for(const sourceLocale of ordered){for(const row of compiled(sourceLocale,category)){if(!matches(sourceFolded,row,sourceCompact))continue;hits.push(Object.freeze({category,sourceLocale,termLength:row.folded.length,termHash:HASH(row.term)}));if(hits.length>=maxHits)return Object.freeze(hits)}}return Object.freeze(hits)}
function localeOrder(locale='en'){const id=String(locale||'en').toLowerCase().split(/[-_]/u)[0];return Object.freeze(Array.from(new Set([id,'en',...Object.keys(ROWS)])))}
function match(text='',locale='en'){const id=String(locale||'en').toLowerCase().split(/[-_]/u)[0],ordered=localeOrder(id),hits={};for(const c of CATEGORIES)hits[c]=scanCategory(text,c,ordered);return Object.freeze({version:VERSION,locale:id,scanMode:'all-32-locales-primary-first',scannedLocaleCount:Object.keys(ROWS).length,bankTermCount:BANK_TERM_COUNT,profanity:hits.profanity.length>0,euphemisms:hits.euphemisms.length>0,directInsults:hits.directInsults.length>0,threats:hits.threats.length>0,hits:Object.freeze(hits)})}
function audit(){const locales=Object.keys(ROWS),failures=[];if(locales.length!==32)failures.push('locale_count:'+locales.length);for(const l of locales)for(const c of CATEGORIES)if(!(ROWS[l]?.[c]?.length))failures.push('missing:'+l+':'+c);return Object.freeze({version:VERSION,localeCount:locales.length,categoryCount:CATEGORIES.length,bankTermCount:BANK_TERM_COUNT,scanAllLocales:true,failures:Object.freeze(failures),ok:failures.length===0})}

